      homeEl.hidden = true;
      qa(panels).forEach((p2) => {
        p2.hidden = true;
      });
      page.hidden = false;
      setChrome(customTitle || page.dataset[titleAttr] || homeTitle, "back");
      const body = page.closest(".settings-body");
